"""Lazy Native construction policy for C158196 yield/active-control probes.

The caller supplies CARLA actors and site observations after checking the map.
This module never creates a sign, crosswalk, or through highway by declaration.
"""

from __future__ import annotations

import math
import hashlib
from pathlib import Path


CASES = {
    "nearest_view_hold": "hold_for_observed_traffic",
    "nearest_view_continue": "continue_through_observed_traffic",
    "nearest_view_clear": "continue_after_clear_observation",
    "active_signal_exception": "observe_signal_governance",
}

SITE_SOURCES = ("map_hash", "device_hash", "raycast_hash", "camera_plan_hash")


def validate_site(site: dict, case: str) -> dict:
    if case not in CASES:
        raise ValueError("unknown exact case")
    if site.get("native_cell_id") != "C158196":
        raise ValueError("wrong Native cell")
    if site.get("layout") != "one_way_to_two_way_intersection":
        raise ValueError("wrong intersection layout")
    if site.get("route_connected") is not True or site.get("through_highway_confirmed") is not True:
        raise ValueError("route and through-highway survey required")
    if site.get("marked_stop_line") is not False:
        raise ValueError("marked stop line exclusion unconfirmed")
    if site.get("near_side_crosswalk") is not False or site.get("sidewalk_derived_crosswalk") is not False:
        raise ValueError("near-side crosswalk exclusion unconfirmed")
    if site.get("officer_controlling") is not False:
        raise ValueError("officer control exclusion unconfirmed")
    if case != "active_signal_exception":
        if site.get("proper_yield_sign") is not True or site.get("yield_sign_governs") is not True:
            raise ValueError("proper governing yield sign not observed")
        if site.get("signal_controlling") is not False:
            raise ValueError("signal exception must be absent in yield case")
    elif site.get("signal_controlling") is not True:
        raise ValueError("active signal exception must be observed")
    view = site.get("nearest_view_station_m")
    entry = site.get("intersection_entry_station_m")
    if any(isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) for v in (view, entry)):
        raise ValueError("Native viewpoint and entry geometry missing")
    if view >= entry:
        raise ValueError("viewpoint must precede intersection entry")
    for source in SITE_SOURCES:
        value = site.get(source)
        if not isinstance(value, str) or len(value) != 64 or any(c not in "0123456789abcdef" for c in value):
            raise ValueError(f"{source} source missing")
    return {"case": case, "engineering_policy": CASES[case], "view_station_m": float(view),
            "entry_station_m": float(entry), "source_hashes": {k: site[k] for k in
            SITE_SOURCES}}


def verify_site_sources(site: dict, case: str, source_root: Path) -> dict:
    """Check original site bytes before a production Native construction is selected."""
    selected = validate_site(site, case)
    root = source_root.resolve()
    files = site.get("source_files")
    if not isinstance(files, dict) or set(files) != set(SITE_SOURCES):
        raise ValueError("four original Native site source files required")
    seen: set[Path] = set()
    for name in SITE_SOURCES:
        entry = files[name]
        if not isinstance(entry, dict) or entry.get("origin") != "original_native":
            raise ValueError(f"{name} original Native provenance required")
        rel = entry.get("path")
        if not isinstance(rel, str) or not rel or Path(rel).is_absolute():
            raise ValueError(f"{name} source path invalid")
        path = (root / rel).resolve()
        if not path.is_relative_to(root) or path in seen or not path.is_file():
            raise ValueError(f"{name} source path missing, duplicate or outside site")
        seen.add(path)
        data = path.read_bytes()
        if not data or hashlib.sha256(data).hexdigest() != site[name]:
            raise ValueError(f"{name} original source hash mismatch")
    return selected


def controller(case: str, site: dict, observed: dict) -> dict:
    """Use observed conflict state for a diagnostic brake policy, not a verdict."""
    construction = validate_site(site, case)
    speed = observed.get("ego_speed_mps")
    front = observed.get("ego_front_station_m")
    if any(isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) for v in (speed, front)):
        raise ValueError("original ego speed and body station required")
    if speed < 0:
        raise ValueError("negative speed")
    occupied = observed.get("through_occupied")
    if not isinstance(occupied, bool):
        raise ValueError("observed through-traffic occupancy required")
    near_view = front >= construction["view_station_m"] - 2.0
    if case == "nearest_view_hold" and near_view and occupied:
        return {"throttle": 0.0, "brake": min(1.0, 0.3 + speed / 8.0),
                "steer": 0.0, "state": "engineering_yield_hold"}
    if case == "nearest_view_clear" and occupied:
        raise ValueError("clear-traffic case has occupied through interval")
    if case == "nearest_view_continue" and not occupied:
        raise ValueError("occupied-traffic comparison missing")
    return {"throttle": max(0.0, min(0.45, (4.0 - speed) * 0.12)),
            "brake": max(0.0, min(0.4, (speed - 4.0) * 0.12)),
            "steer": 0.0, "state": "engineering_approach"}

"""Source-gated measurement for the yield sign's nearest-view branch.

Inputs are original-tick observations, not commanded speeds or legal findings.
The runner must obtain the context from Native map/device/readback sources.
"""

from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path


REQUIRED_SOURCES = (
    "native_map", "yield_sign_readback", "signal_state_readback",
    "officer_observation", "stop_line_survey", "crosswalk_survey",
    "sidewalk_survey", "through_highway_survey", "view_raycast",
)


def _number(value: object, name: str) -> float:
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
        raise ValueError(f"{name} must be finite")
    return float(value)


def _source(item: object, name: str) -> None:
    if not isinstance(item, dict) or not isinstance(item.get("path"), str) or not item["path"]:
        raise ValueError(f"{name} source path missing")
    digest = item.get("sha256")
    if not isinstance(digest, str) or len(digest) != 64 or any(c not in "0123456789abcdef" for c in digest):
        raise ValueError(f"{name} source hash missing")


def verify_source_bytes(packet: dict, packet_dir: Path) -> None:
    """Bind each declared original source to bytes inside the saved attempt."""
    base = packet_dir.resolve()
    for name in REQUIRED_SOURCES:
        item = packet["sources"].get(name)
        _source(item, name)
        relative = Path(item["path"])
        if relative.is_absolute() or ".." in relative.parts:
            raise ValueError(f"{name} source escapes attempt")
        path = (base / relative).resolve()
        if not path.is_relative_to(base) or not path.is_file():
            raise ValueError(f"{name} source bytes missing")
        if hashlib.sha256(path.read_bytes()).hexdigest() != item["sha256"]:
            raise ValueError(f"{name} source hash mismatch")


def measure(packet: dict) -> dict:
    """Measure observed ordering and conflict interval; leave legal judgment open."""
    context = packet["context"]
    sources = packet["sources"]
    for name in REQUIRED_SOURCES:
        _source(sources.get(name), name)
    if context.get("cell_id") != "C158196" or context.get("law_id") != "NRS-484B-257-1":
        raise ValueError("wrong exact cell or law")
    required_true = ("proper_yield_sign", "through_highway", "connected_approach")
    required_false = ("marked_stop_line", "near_side_crosswalk", "sidewalk_derived_crosswalk",
                      "officer_controlling", "signal_controlling")
    for name in required_true:
        if context.get(name) is not True:
            raise ValueError(f"{name} not source-confirmed")
    for name in required_false:
        if context.get(name) is not False:
            raise ValueError(f"{name} must be source-confirmed absent")
    view_station = _number(context.get("nearest_view_station_m"), "nearest_view_station_m")
    entry_station = _number(context.get("intersection_entry_station_m"), "intersection_entry_station_m")
    if view_station >= entry_station:
        raise ValueError("nearest-view point must precede intersection entry")
    frames = packet["frames"]
    if not isinstance(frames, list) or len(frames) < 3:
        raise ValueError("original frame history too short")
    first = frames[0]
    base_frame = first.get("frame")
    base_time = _number(first.get("time_s"), "time_s")
    if not isinstance(base_frame, int) or isinstance(base_frame, bool):
        raise ValueError("original frame number missing")
    first_view = None
    first_entry = None
    crossing = []
    prior_front = None
    for i, item in enumerate(frames):
        if item.get("frame") != base_frame + i:
            raise ValueError("original frames not contiguous")
        if abs(_number(item.get("time_s"), "time_s") - (base_time + i / 20)) > 0.001:
            raise ValueError("original timestamps not 20 Hz")
        front = _number(item.get("ego_front_station_m"), "ego_front_station_m")
        speed = _number(item.get("ego_speed_mps"), "ego_speed_mps")
        through = _number(item.get("through_center_station_m"), "through_center_station_m")
        if speed < 0:
            raise ValueError("negative physical speed")
        for key in ("view_clear", "through_occupied", "ego_within_intersection"):
            if not isinstance(item.get(key), bool):
                raise ValueError(f"{key} original observation missing")
        if prior_front is not None and front < prior_front - 0.2:
            raise ValueError("ego approach reversed beyond measurement tolerance")
        prior_front = front
        if first_view is None and front >= view_station and item["view_clear"]:
            first_view = i
        if first_entry is None and front >= entry_station:
            first_entry = i
        if item["ego_within_intersection"]:
            crossing.append(i)
    if first_view is None or first_entry is None or first_view >= first_entry:
        raise ValueError("observed view must precede actual entry")
    if not crossing or crossing[0] < first_entry:
        raise ValueError("crossing history missing or precedes entry")
    approach = frames[:first_entry + 1]
    return {
        "first_view_frame": frames[first_view]["frame"],
        "first_entry_frame": frames[first_entry]["frame"],
        "minimum_approach_speed_mps": min(x["ego_speed_mps"] for x in approach),
        "through_center_at_view_m": frames[first_view]["through_center_station_m"],
        "through_occupied_during_crossing": any(frames[i]["through_occupied"] for i in crossing),
        "crossing_frame_count": len(crossing),
        "legal_immediate_hazard": "unresolved_judgment",
        "legal_right_of_way": "unresolved_judgment",
    }


def compare(left: dict, right: dict, *, differing: tuple[str, ...]) -> dict:
    """Reject undeclared context changes and measure both original histories."""
    allowed = set(differing)
    for key in set(left["context"]) | set(right["context"]):
        if key not in allowed and left["context"].get(key) != right["context"].get(key):
            raise ValueError(f"unreviewed fixed-condition change: {key}")
    measured = [measure(left), measure(right)]
    return {"left": measured[0], "right": measured[1],
            "declared_differences": sorted(allowed), "comparison_status": "measured_not_legal_verdict"}


def main(path: Path, output: Path) -> None:
    raw = path.read_bytes()
    packet = json.loads(raw)
    verify_source_bytes(packet, path.parent)
    measured = measure(packet)
    output.write_text(json.dumps({"input_sha256": hashlib.sha256(raw).hexdigest(),
                                  "measurement": measured}, indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument("packet", type=Path)
    parser.add_argument("output", type=Path)
    args = parser.parse_args()
    main(args.packet, args.output)

"""Derive one C158196 measurement row from an original Native tick.

The caller supplies actual CARLA body corners, velocity, snapshot and raycast.
This adapter does not infer legal right of way or fabricate a camera frame.
"""

from __future__ import annotations

import math

from shapely.geometry import Point, Polygon


def _number(value: object, name: str) -> float:
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
        raise ValueError(f"{name} must be finite")
    return float(value)


def _point(value: object, name: str) -> tuple[float, float]:
    if not isinstance(value, (list, tuple)) or len(value) != 2:
        raise ValueError(f"{name} requires XY coordinates")
    return _number(value[0], name), _number(value[1], name)


def _body(value: object, name: str) -> Polygon:
    if not isinstance(value, list) or len(value) != 4:
        raise ValueError(f"{name} requires four original body corners")
    polygon = Polygon([_point(p, name) for p in value])
    if not polygon.is_valid or polygon.area <= 0:
        raise ValueError(f"{name} body geometry invalid")
    return polygon


def _axis(value: object, name: str) -> tuple[float, float]:
    axis = _point(value, name)
    if abs(math.hypot(*axis) - 1.0) > 1e-4:
        raise ValueError(f"{name} must be a unit direction")
    return axis


def _station(point: tuple[float, float], origin: tuple[float, float],
             axis: tuple[float, float]) -> float:
    return (point[0] - origin[0]) * axis[0] + (point[1] - origin[1]) * axis[1]


def derive(raw: dict, geometry: dict, *, expect_signal: bool = False) -> dict:
    frame = raw.get("frame")
    if isinstance(frame, bool) or not isinstance(frame, int) or frame < 0:
        raise ValueError("original snapshot frame missing")
    time = _number(raw.get("time_s"), "original snapshot time")
    ego = _body(raw.get("ego_body_xy_m"), "ego")
    through = _body(raw.get("through_body_xy_m"), "through")
    velocity = _point(raw.get("ego_velocity_xy_mps"), "ego velocity")
    center = _point(raw.get("through_center_xy_m"), "through center")
    if not through.covers(Point(center)):
        raise ValueError("through center differs from observed body")
    ray = raw.get("native_view_raycast")
    if not isinstance(ray, dict) or ray.get("source") != "native_raycast":
        raise ValueError("original Native visibility raycast required")
    if not isinstance(ray.get("occluded"), bool):
        raise ValueError("raycast occlusion state missing")
    start = _point(ray.get("origin_xy_m"), "ray origin")
    target = _point(ray.get("target_xy_m"), "ray target")
    if not ego.covers(Point(start)) or not through.covers(Point(target)):
        raise ValueError("raycast endpoint differs from observed bodies")
    if raw.get("yield_sign_readback") is not True:
        raise ValueError("original yield sign readback required")
    if raw.get("signal_controlling") is not expect_signal or raw.get("officer_controlling") is not False:
        raise ValueError("original controlling exception state differs")
    ego_origin = _point(geometry.get("ego_route_origin_xy_m"), "ego route origin")
    ego_axis = _axis(geometry.get("ego_route_axis_xy"), "ego route axis")
    through_origin = _point(geometry.get("through_route_origin_xy_m"), "through route origin")
    through_axis = _axis(geometry.get("through_route_axis_xy"), "through route axis")
    region = _body(geometry.get("intersection_polygon_xy_m"), "intersection")
    front = max(_station((x, y), ego_origin, ego_axis) for x, y in ego.exterior.coords[:-1])
    return {"frame": frame, "time_s": time,
            "ego_front_station_m": front, "ego_speed_mps": math.hypot(*velocity),
            "through_center_station_m": _station(center, through_origin, through_axis),
            "view_clear": not ray["occluded"],
            "through_occupied": through.intersects(region),
            "ego_within_intersection": ego.intersects(region)}
